            lib.element.player.sbzzupdatecardsba = function () {
                if (!game.me) return;
                var handNode = ui.handcards1;
                if (!handNode) return console.warn('hand undefined');
                var card;
                var cards = [];
                var childs = handNode.childNodes;
                for (let i = 0; i < childs.length; i++) {
                    card = childs[i];
                    if (!card.classList.contains('removing')) {
                        cards.push(card);
                    } else {
                        card.scaled = false;
                    }
                }
                if (!cards.length) return;
                var pw = 577;
                var ph = 149;
                var cw = 108;
                var ch = 150;
                var cs = 0.788;
                cs = 1;
                var csw = cw * cs;
                var x;
                var y = Math.round((ch * cs - ch) / 2);
                var xMargin = csw + 2;
                var xStart = (csw - cw) / 2;
                var totalW = cards.length * csw + (cards.length - 1) * 2;
                var limitW = pw;
                var expand;
                if (totalW > limitW) {
                    xMargin = csw - Math.abs(limitW - csw * cards.length) / (cards.length - 1);
                    if (lib.config.fold_card) {
                        var foldCardMinWidth = 20;
                        var min = cs;
                        if (foldCardMinWidth == 'cardWidth') {
                            min *= 1.5;
                        } else {
                            min *= foldCardMinWidth && foldCardMinWidth.length ? 1.5 : 1.5;
                        }
                        if (xMargin < 1000) {
                            expand = true;
                            xMargin = 1.5;
                        }
                    }
                } else {
                    xStart += 0;
                }
                var card;
                var zhencard = [];
                var jiacard = [];
                var jias = 0;
                if (Array.isArray(cards)) for (const i of cards) {
                    if (i.hasGaintag && i.hasGaintag('sbzz_huizhi_1')) {
                        jias++;
                    }
                }
                var zhenshu = 0;
                if (jias < cards.length) {
                    zhenshu++;
                }
                if (jias == 0) jias = 1;
                var zdd = 1.5;
                pw = pw + 0.5 * csw;
                if (jias * (csw - 1.5) + cards.length * 1.5 < 0.9 * pw) {
                    var kdd = csw;
                    if (cards.length <= jias) {
                        zdd = 0;
                    } else {
                        zdd = (0.9 * pw - csw * jias) / (cards.length - jias);
                    }
                    if (zdd > csw) {
                        zdd = csw;
                    }
                    if (zdd > 1.5) {
                        zdd = 1.5;
                    }
                } else {
                    if (jias < 2) jias = 2;
                    var kdd = Math.max(0.2 * csw, (0.9 * pw - csw - (cards.length - jias) * 1.5) / (jias - 1));
                    if (kdd == 0.2 * csw) {
                        zdd = 0;
                        kdd = Math.min((0.9 * pw - csw) / (jias - 1), csw);
                    }
                }
                var xzpb = xStart - zdd;
                if (zhenshu > 0) xzpb = xzpb + kdd;
                for (const i of cards) {
                    if (!i.hasGaintag || !i.hasGaintag('sbzz_huizhi_1')) {
                        x = Math.round(xzpb + zdd);
                        if ((!i.hasGaintag || !i.hasGaintag('sbzz_huizhi_1')) && zhenshu > 0) x = x - kdd + zdd;
                        xzpb += zdd;
                        card = i;
                        card.tx = x;
                        card.ty = y;
                        card.scaled = true;
                        card.style.transform = 'translate(' + x + 'px,' + y + 'px) scale(' + cs + ')';
                        card._transform = card.style.transform;
                    } else {
                        x = Math.round(xzpb + kdd);
                        xzpb += kdd;
                        card = i;
                        card.tx = x;
                        card.ty = y;
                        card.scaled = true;
                        card.style.transform = 'translate(' + x + 'px,' + y + 'px) scale(' + cs + ')';
                        card._transform = card.style.transform;
                    }
                }//QQQ
            };
