                                var num = 0;
                                if (player.countCards('h') > 0) {
                                    for (const i of player.getCards('h')) {
                                        if (get.type(i) != 'equip') {
                                            if (player.canUse(i, player) && player.getUseValue(i) > 0 && (get.type(i) == 'equip' || ['tao', 'wuzhong', 'dongzhuxianji'].includes(i.name))) num++;
                                        } else {
                                            var num1 = 0;
                                            if (player.countCards('e') > 0) {
                                                for (var j of player.getCards('e')) {
                                                    if (get.subtype(j) == get.subtype(i)) num1 = player.getUseValue(j);
                                                }
                                            }
                                            if (player.canUse(i, player) && player.getUseValue(i) - num1 > 0) num++;
                                        }
                                    }
                                }
                                if (player.isPhaseUsing()) return num == 0;
                                return player.countCards('h') <= 2 || (num == 0 && player.countCards('h') <= 4);
