                                    var target = event.player;
                                    if (event.getParent(2).jiu == true) return false;
                                    var eff = get.damageEffect(target, player, player, event.nature);
                                    if (get.attitude(player, target) > 0) {
                                        if (eff >= 0) return false;
                                        return true;
                                    }
                                    if (eff <= 0) return true;
                                    if (target.hp >= 2 && target.getCards('he') && target.getCards('he').length > 2 && player.hasSkill('sbzz_chiyanxiang')) return true;
                                    if (target.hp == 1) return false;
                                    if (event.num > 1 || player.hasSkill('tianxianjiu') || player.hasSkill('luoyi2') || player.hasSkill('reluoyi2')) return false;
                                    if (_status.currentPhase && player == _status.currentPhase && player.hasSkill('sbzz_fuxie') && !target.hasSkill('sbzz_fuxie_1') && event.getParent(2).jiu != true) return true;
                                    if (target.countCards('he') < 2) return false;
