                        sbzz_yezhan: {
                            audio: 'ext:圣杯战争/audio:3',
                            trigger: {
                                player: ['phaseBegin'],
                            },
                            forced: true,
                            content() {
                                'step 0';
                                player
                                    .chooseTarget(get.prompt2('sbzz_yezhan'), function (card, player, target) {
                                        return target.hp == target.hp;
                                    })
                                    .set('ai', function (target) {
                                        var player = _status.event.player;
                                        var att = get.attitude(player, target);
                                        var nh = target.countCards('h');
                                        if (nh < 4 && att > 0) {
                                            return att * (8 - nh * 2);
                                        }
                                        if (nh >= 4 && target != player && att < 0) {
                                            return -2 * att * (nh - 2);
                                        }
                                        if (nh < 4 && att < 0) {
                                            return -2 * att * (nh - 1);
                                        }
                                        return att;
                                    });
                                ('step 1');
                                if (result.bool) {
                                    event.target = result.targets[0];
                                    if (event.target.countCards('h')) {
                                        player
                                            .chooseControl(function (event, player) {
                                                var target = event.target;
                                                if (get.attitude(player, target) < 0) return 1;
                                                return 0;
                                            })
                                            .set('choiceList', ['令' + get.translation(event.target) + '补牌', '拆' + get.translation(event.target) + '的手牌']);
                                    } else {
                                        event.directfalse = true;
                                    }
                                } else {
                                    event.finish();
                                }
                                ('step 2');
                                if (event.directfalse || result.index == 0) {
                                    if (event.target.getCards('h').length) event.target.showHandcards();
                                    var suits = ['heart', 'club', 'spade', 'diamond'],
                                        cards = [],
                                        hs = event.target.getCards('h');
                                    for (const i of hs) {
                                        suits.remove(i.suit);
                                    }
                                    for (const i of suits) {
                                        var card = get.cardPile(function (card) {
                                            return card.suit == i;
                                        });
                                        if (card) cards.push(card);
                                    }
                                    if (cards.length) event.target.gain(cards, 'gain2', 'log');
                                    if (cards.length && suits.length && suits.length > cards.length) event.target.draw(suits.length - cards.length);
                                    event.finish();
                                }
                                ('step 3');
                                if (event.target.getCards('h').length) event.target.showHandcards();
                                event.list1 = [];
                                event.list2 = [];
                                var chooseButton = player.chooseButton([1, 4], true, [get.translation(target.name) + '的手牌', target.getCards('h')]);
                                chooseButton.set('target', target);
                                chooseButton.set('ai', function (button) {
                                    var target = event.target;
                                    var ts = [];
                                    for (let i = 0; i < ui.selected.buttons.length; i++) {
                                        var card = ui.selected.buttons[i].link;
                                        if (target.getCards('h').includes(card)) ts.push(card);
                                    }
                                    var card = button.link;
                                    var owner = get.owner(card);
                                    var val = get.value(card) || 1;
                                    if (owner == target) {
                                        return 2 * val;
                                    }
                                    return 7 - val;
                                });
                                chooseButton.set('filterButton', function (button) {
                                    for (let i = 0; i < ui.selected.buttons.length; i++) {
                                        if (button.link.suit == ui.selected.buttons[i].link.suit) return false;
                                    }
                                    return true;
                                });
                                ('step 4');
                                if (result.bool) {
                                    var list = result.links;
                                    for (let i = 0; i < list.length; i++) {
                                        if (get.owner(list[i]) == player) {
                                            event.list1.push(list[i]);
                                        } else {
                                            event.list2.push(list[i]);
                                        }
                                    }
                                    if (event.list1.length || event.list2.length) {
                                        target.discard(event.list2).delay = false;
                                        player.discard(event.list1);
                                        target.draw();
                                    }
                                }
                            },
                        },
