                                ('step 1');
                                var tosave = player;
                                var att = get.attitude(player, tosave);
                                var hastao = player.countCards('h', 'tao');
                                player
                                    .chooseToDiscard(2, true, 'he')
                                    .set('ai', function (card) {
                                        var hastao = _status.event.hastao;
                                        var att = get.attitude(player, tosave);
                                        if (player.hp < player.maxHp) {
                                            var suit = card.suit;
                                            if (!player.getStorage('sbzz_tongxing').includes(suit) && !ui.selected.cards[0]) {
                                                return 10 - get.value(card);
                                            }
                                            if (!player.getStorage('sbzz_tongxing').includes(suit) && ui.selected.cards[0] && ui.selected.cards[0].suit == suit) {
                                                return 15 - get.value(card);
                                            }
                                        }
                                        if (player.hp == player.maxHp) {
                                            var suit = card.suit;
                                            if (!player.getStorage('sbzz_tongxing').includes(suit) && !ui.selected.cards[0]) {
                                                return 4 - get.value(card);
                                            }
                                            if (!player.getStorage('sbzz_tongxing').includes(suit) && ui.selected.cards[0] && ui.selected.cards[0].suit == suit) {
                                                return 7 - get.value(card);
                                            }
                                        }
                                        return -get.value(card);
                                    })
                                    .set('hastao', hastao)
                                    .set('att', att);
                                ('step 2');
                                if (result.cards && result.cards.length) {
                                    var suit = [];
                                    var n = 0;
                                    if (Array.isArray(result.cards)) for (const i of result.cards) {
                                        suit.add(i.suit);
                                        if (!player.getStorage('sbzz_tongxing').includes(i.suit)) {
                                            n++;
                                        }
                                    }
                                    if (Array.isArray(result.cards)) for (const i of result.cards) {
                                        suit.add(i.suit);
                                        if (!player.getStorage('sbzz_tongxing').includes(i.suit)) {
                                            player.getStorage('sbzz_tongxing').add(i.suit);
                                        }
                                    }
                                    if (n == result.cards.length) {
                                        if (player.hp < player.maxHp) player.recover();
                                    }
                                } else if (player.hp < player.maxHp) player.recover();
                                ('step 3');
